<template>
  <main class="bi-page">
    <header class="page-head">
      <div class="head-title"><RouterLink to="/dashboard" class="back" aria-label="Voltar ao dashboard"><ArrowLeft :size="20" /></RouterLink><div><span class="eyebrow">INTELIGÊNCIA ELEVEN</span><h1>Visão de vendas</h1><p>Seu negócio em números. O Excel continua sendo a fonte.</p></div></div>
      <div class="head-actions"><button @click="tab='sources'"><Database :size="16"/>Fontes</button><button class="primary" :disabled="refreshing || status?.running || !status?.configured || !status?.enabled" @click="refresh"><RefreshCw :size="16" :class="{spin:status?.running}"/>{{status?.running ? 'Atualizando…' : 'Atualizar dados'}}</button></div>
    </header>
    <div v-if="error" role="alert" class="alert error">{{error}}<button aria-label="Fechar aviso" @click="error=''">×</button></div>
    <div v-if="notice" role="status" class="alert success">{{notice}}<button aria-label="Fechar aviso" @click="notice=''">×</button></div>
    <div class="sync-line"><span :class="['dot', {working:status?.running, warning:!!status?.error}]"/><span>{{ status?.running ? 'Lendo as planilhas do OneDrive…' : status?.finished_at ? `Última verificação ${date(status.finished_at)}` : 'Aguardando a primeira leitura' }}</span><span class="sync-detail">Atualização automática a cada 15 minutos · Somente leitura</span></div>
    <div v-if="status?.error" class="alert caution" role="status"><span>Algumas fontes não puderam ser atualizadas. Os últimos dados disponíveis foram mantidos.</span><button @click="tab='sources'">Ver fontes</button></div>
    <nav class="tabs" aria-label="Análises de vendas"><button v-for="t in tabs" :key="t.id" :class="{selected:tab===t.id}" @click="tab=t.id"><component :is="t.icon" :size="17"/>{{t.label}}</button></nav>

    <section v-if="tab !== 'sources'" class="filters" aria-label="Filtros do painel">
      <label>Ano<select v-model.number="year" @change="load"><option :value="0">Todo o histórico</option><option v-for="y in data?.years" :key="y" :value="y">{{y}}</option></select></label>
      <label>Mês<select v-model.number="month" @change="load"><option :value="0">Todos os meses</option><option v-for="(m,i) in monthNames" :key="m" :value="i+1">{{m}}</option></select></label>
      <label>Vendedor<select v-model="seller" @change="load"><option value="">Toda a equipe</option><option v-for="s in data?.sellers" :key="s">{{s}}</option></select></label>
      <div class="filter-caption"><span class="badge">{{periodLabel}}</span><small>Totais em US$ conforme os resultados salvos.</small></div>
    </section>
    <div v-if="loading && !data" class="empty panel"><RefreshCw class="spin" :size="28"/><h2>Preparando sua visão de vendas</h2></div>
    <section v-else-if="data && !data.years.length && tab!=='sources'" class="empty panel"><BarChart3 :size="38"/><h2>{{status?.running?'Lendo o histórico…':'As vendas começam nas suas planilhas'}}</h2><p>{{status?.configured?'O painel aparecerá após a primeira leitura do OneDrive.':'Conecte a planilha atual e a pasta dos meses anteriores para começar.'}}</p><button @click="tab='sources'">Acompanhar fontes</button></section>
    <template v-else-if="data && tab !== 'sources'">
      <div :aria-busy="loading" :class="{updating:loading}">
        <section class="metrics">
          <article class="metric featured"><span>Vendas do período <span v-if="data.selected.partial" class="badge">Em andamento</span></span><strong>{{usd(data.selected.total_usd)}}</strong><small>{{seller || 'Toda a equipe'}} · {{data.selected.available_months}} de {{data.selected.source_months}} meses disponíveis</small><TrendingUp :size="23"/></article>
          <article class="metric"><span>{{year ? `Acumulado de ${year}` : 'Acumulado do histórico'}}</span><strong>{{usd(annualTotal)}}</strong><small>{{annualCoverage}} meses com dados{{year===data.latest.year ? ' · até o último mês disponível' : ''}}</small><CalendarDays :size="21"/></article>
          <article class="metric"><span>{{seller ? 'Posição no período' : 'Maior resultado por vendedor'}}</span><strong class="name">{{seller ? sellerPosition : data.ranking[0]?.name || '—'}}</strong><small>{{seller ? seller : usd(data.ranking[0]?.total_usd)}} · resultados disponíveis</small><Trophy :size="21"/></article>
          <article class="metric"><span>Melhor semana do período</span><strong>{{usd(data.weeks[0]?.total_usd)}}</strong><small>{{data.weeks[0] ? `${data.weeks[0].label} · ${data.weeks[0].year}` : 'Nenhuma semana disponível'}}</small><ChartNoAxesCombined :size="21"/></article>
        </section>
        <p v-if="data.selected.available_months < data.selected.source_months || data.coverage.warnings" class="data-note"><Info :size="16"/><span>Alguns arquivos têm detalhamento incompleto. Valores ausentes aparecem como “—” e não entram nos rankings. Confira a cobertura de cada resultado em <button class="text-button" @click="tab='sources'">Fontes</button>.</span></p>

        <template v-if="tab==='overview'">
          <div class="analysis-grid">
            <section class="panel trend-panel"><div class="section-head"><div><span class="eyebrow">EVOLUÇÃO</span><h2>Vendas mês a mês</h2><p>{{seller || 'Resultado geral da loja'}} · {{year || 'todos os anos disponíveis'}}</p></div><span class="badge">US$</span></div><div class="chart"><Line :data="trendChart" :options="lineOptions" aria-label="Evolução mensal das vendas em dólares" role="img"/></div><small>Meses sem planilha ficam em branco. O mês em andamento ainda pode mudar.</small></section>
            <section class="panel ranking-panel"><div class="section-head"><div><span class="eyebrow">EQUIPE</span><h2>Ranking de vendedores</h2><p>{{periodLabel}}</p></div><Users :size="21"/></div><div v-if="!data.ranking.length" class="empty small-empty">Não há resultados por vendedor neste período.</div><button v-for="(r,i) in data.ranking" :key="r.name" class="rank-row" :class="{chosen:seller===r.name}" @click="seller=seller===r.name?'':r.name;load()"><span class="rank-index">{{i+1}}</span><div class="rank-content"><div><strong>{{r.name}}</strong><b>{{usd(r.total_usd)}}</b></div><div class="bar-track"><span :style="{width:rankWidth(r.total_usd)+'%'}"/></div><small>{{r.available_months}} de {{r.source_months}} meses disponíveis</small></div></button></section>
          </div>
          <section class="panel currencies"><div class="section-head"><div><span class="eyebrow">MOEDAS</span><h2>Valores em cada moeda</h2><p>Resultados salvos nos resumos por moeda, sem aplicar uma nova cotação.</p></div><Coins :size="22"/></div><div class="currency-grid"><article v-for="c in data.currencies" :key="c.currency"><span>{{currencyNames[c.currency]}}</span><strong>{{amount(c.value,c.currency)}}</strong><small>{{c.available_months}} de {{c.source_months}} meses com detalhamento</small></article></div></section>
          <section class="panel"><div class="section-head"><div><h2>Resultados mensais</h2><p>Um resultado por mês, mesmo quando a planilha atual já foi arquivada.</p></div><button :disabled="!visibleMonths.length" @click="exportCsv"><Download :size="16"/>Exportar resumo</button></div><div class="table-wrap"><table><thead><tr><th>Período</th><th>Fonte</th><th>Atualização dos dados</th><th class="numeric">{{seller || 'Total da loja'}} · US$</th></tr></thead><tbody><tr v-for="m in visibleMonths" :key="`${m.year}-${m.month}`"><td><button class="text-button" @click="year=m.year;month=m.month;load()">{{monthNames[m.month-1]}} / {{m.year}}</button><span v-if="m.partial" class="badge partial">Em andamento</span></td><td>{{m.filename}}<small>{{m.source_cell || 'Resumos semanais disponíveis'}}</small></td><td>{{date(m.synced_at)}}<small v-if="m.stale" class="warning-text">Última leitura válida</small></td><td class="numeric"><strong>{{usd(m.total_usd)}}</strong></td></tr></tbody></table><p v-if="!visibleMonths.length" class="empty">Nenhuma planilha disponível para este período.</p></div></section>
        </template>

        <template v-if="tab==='compare'">
          <section class="panel"><div class="section-head"><div><span class="eyebrow">MESMO MÊS, OUTROS ANOS</span><h2>{{monthNames[data.comparison_month-1]}} ao longo dos anos</h2><p>{{seller || 'Toda a equipe'}} · selecione os anos para comparar</p></div></div><div class="year-chips"><label v-for="y in data.years" :key="y" :class="{on:compareYears.includes(y)}"><input v-model="compareYears" type="checkbox" :value="y"/>{{y}}</label></div><div class="chart comparison-chart"><Bar :data="comparisonChart" :options="barOptions" role="img" aria-label="Comparação do mesmo mês entre anos"/></div><div class="table-wrap"><table><thead><tr><th>Ano</th><th class="numeric">Vendas · US$</th><th class="numeric">Diferença entre anos selecionados</th><th>Situação</th></tr></thead><tbody><tr v-for="m in comparisonRows" :key="m.year"><td><strong>{{m.year}}</strong></td><td class="numeric">{{usd(m.total_usd)}}</td><td class="numeric"><span :class="{'positive':(m.delta||0)>0,'negative':(m.delta||0)<0}">{{m.delta===null ? '—' : `${m.delta>=0?'+':''}${usd(m.delta)}`}}</span><small v-if="m.previous">vs. {{m.previous}}{{m.percent===null ? '' : ` · ${m.percent.toLocaleString('pt-BR',{maximumFractionDigits:1})}%`}}</small></td><td><span class="badge" :class="{partial:m.partial}">{{m.total_usd===null?'Sem detalhamento':m.partial?'Mês em andamento':'Arquivo mensal'}}</span></td></tr></tbody></table></div><p v-if="comparisonRows.some(m=>m.partial)" class="data-note"><Info :size="16"/>A comparação inclui um mês em andamento. Ela não representa a variação entre meses completos.</p></section>
          <section class="panel"><h2>Acumulado por ano</h2><p>Soma dos meses disponíveis de cada ano. Anos com cobertura diferente não representam períodos equivalentes.</p><div class="table-wrap"><table><thead><tr><th>Ano</th><th>Meses com resultado</th><th class="numeric">{{seller || 'Toda a equipe'}} · US$</th></tr></thead><tbody><tr v-for="a in data.annual" :key="a.year"><td><strong>{{a.year}}</strong></td><td>{{a.available_months}} de {{a.source_months}} disponíveis <span v-if="a.partial" class="badge partial">Em andamento</span></td><td class="numeric">{{usd(a.total_usd)}}</td></tr></tbody></table></div></section>
        </template>

        <section v-if="tab==='weeks'" class="panel"><div class="section-head"><div><span class="eyebrow">DESTAQUES</span><h2>Semanas que mais venderam</h2><p>{{periodLabel}} · {{seller || 'Toda a equipe'}}. Os períodos seguem a organização das suas planilhas.</p></div><select v-model.number="weekLimit" aria-label="Quantidade de semanas"><option :value="10">Top 10</option><option :value="25">Top 25</option><option :value="1000">Todas</option></select></div><div class="table-wrap"><table><thead><tr><th>Posição</th><th>Semana</th><th>Mês / ano</th><th class="numeric">Vendas · US$</th></tr></thead><tbody><tr v-for="(w,i) in data.weeks.slice(0,weekLimit)" :key="`${w.year}-${w.month}-${w.index}`"><td><span class="rank-index" :class="{medal:i<3}">{{i+1}}</span></td><td><strong>{{w.label}}</strong><small>Período {{w.index}} da planilha</small></td><td>{{monthNames[w.month-1]}} / {{w.year}} <span v-if="w.partial" class="badge partial">Mês em andamento</span></td><td class="numeric"><strong>{{usd(w.total_usd)}}</strong></td></tr></tbody></table><p v-if="!data.weeks.length" class="empty">Não há semanas com resultado disponível para estes filtros.</p></div></section>
      </div>
    </template>

    <template v-if="tab==='sources'">
      <section class="panel source-intro"><div><span class="eyebrow">CONEXÃO COM O EXCEL</span><h2>Suas planilhas, sempre como fonte</h2><p>O ERP consulta os resultados salvos e mantém uma cópia dos resumos para exibição. Continue lançando as vendas no Excel e salve as alterações para atualizar o painel.</p><p class="muted">Leitura automática a cada 15 minutos. Nenhuma célula ou venda do ERP é alterada por esta conexão.</p></div><button v-if="auth.user?.role==='ADMIN'" @click="openConfig"><Settings2 :size="16"/>Configurar fontes</button></section>
      <div v-if="configOpen" class="panel config-panel"><h2>Fontes do OneDrive</h2><form @submit.prevent="saveConfig"><label>Link compartilhado da VendasGeral<input v-model="config.current_url" type="url" required autocomplete="off"/></label><label>Link compartilhado da pasta de históricos<input v-model="config.archive_url" type="url" required autocomplete="off"/></label><label>Caminho da pasta no OneDrive<input v-model="config.archive_root" required placeholder="/personal/…/Documents/…" autocomplete="off"/></label><p>Organize os históricos em pastas de ano, com o nome do mês no arquivo. Exemplo: 2025 / Setembro-Faturamento.xlsx.</p><details><summary>Período da planilha atual</summary><p>Deixe automático para usar o ano e as datas do resumo. Preencha ambos apenas se a planilha não informar o período.</p><div class="config-period"><label>Ano<input v-model.number="config.current_year" type="number" min="2000" max="2100" placeholder="Automático"/></label><label>Mês<select v-model="config.current_month"><option :value="null">Automático</option><option v-for="(m,i) in monthNames" :key="m" :value="i+1">{{m}}</option></select></label></div></details><label class="check"><input v-model="config.enabled" type="checkbox"/>Atualização automática ativa</label><div class="form-actions"><button type="button" @click="configOpen=false">Fechar</button><button type="submit" class="primary" :disabled="saving || status?.running">{{saving?'Salvando…':'Salvar fontes'}}</button></div></form></div>
      <section class="panel"><div class="section-head"><div><h2>Histórico de leitura</h2><p>{{status?.sources.length || 0}} fontes encontradas · {{data?.coverage.months || 0}} meses disponíveis</p></div><label class="check"><input v-model="onlyIssues" type="checkbox"/>Mostrar pendências</label></div><div class="table-wrap"><table><thead><tr><th>Planilha</th><th>Período</th><th>Última leitura válida</th><th>Situação</th></tr></thead><tbody><tr v-for="s in visibleSources" :key="s.id"><td><strong>{{s.filename}}</strong><small>{{s.kind==='current'?'Planilha atual':'Histórico OneDrive'}}</small></td><td>{{s.month ? monthNames[s.month-1] : '—'}} {{s.year || ''}}</td><td>{{date(s.synced_at)}}</td><td><span class="badge" :class="{'issue':!!s.error,'partial':!s.error && !!s.warnings.length}">{{s.error?'Falha na leitura':!s.has_data?'Aguardando leitura':!s.selected?'Arquivo mensal já selecionado':s.warnings.length?'Detalhamento parcial':'Atualizado'}}</span><small v-if="s.error" class="warning-text">{{s.error}}</small><details v-if="s.warnings.length"><summary>Sobre os dados disponíveis</summary><p v-for="w in s.warnings" :key="w">{{w}}</p></details></td></tr></tbody></table><p v-if="!visibleSources.length" class="empty">{{onlyIssues?'Nenhuma pendência nas fontes.':'Nenhuma planilha lida ainda.'}}</p></div></section>
    </template>
  </main>
</template>

<script setup lang="ts">
import {computed, onMounted, onUnmounted, ref} from 'vue'
import {RouterLink} from 'vue-router'
import {ArrowLeft, BarChart3, CalendarDays, ChartNoAxesCombined, Coins, Database, Download, GitCompareArrows, Info, RefreshCw, Settings2, TrendingUp, Trophy, Users} from 'lucide-vue-next'
import {Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, BarElement, Tooltip, Legend, Filler, type ChartOptions} from 'chart.js'
import {Line, Bar} from 'vue-chartjs'
import {salesBi, type Overview, type SourceStatus, type SourceConfig} from '@/services/salesBi'
import {useAuthStore} from '@/stores/auth'
ChartJS.register(CategoryScale,LinearScale,PointElement,LineElement,BarElement,Tooltip,Legend,Filler)
const auth=useAuthStore()
const monthNames=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro']
const currencyNames:Record<string,string>={USD:'Dólar · US$',BRL:'Real · R$',PYG:'Guarani · G$',EUR:'Euro · €'}
const palette=['#2563eb','#10b981','#8b5cf6','#f59e0b','#f43f5e','#64748b']
const tabs=[{id:'overview',label:'Visão geral',icon:BarChart3},{id:'compare',label:'Comparar meses',icon:GitCompareArrows},{id:'weeks',label:'Melhores semanas',icon:Trophy},{id:'sources',label:'Fontes',icon:Database}]
const tab=ref('overview'),year=ref(0),month=ref(0),seller=ref(''),compareYears=ref<number[]>([]),weekLimit=ref(10)
const data=ref<Overview|null>(null),status=ref<SourceStatus|null>(null),loading=ref(false),refreshing=ref(false),saving=ref(false)
const error=ref(''),notice=ref(''),configOpen=ref(false),onlyIssues=ref(false)
const config=ref<SourceConfig>({current_url:'',archive_url:'',archive_root:'',current_year:null,current_month:null,enabled:true})
let sequence=0, timer:ReturnType<typeof setInterval>|undefined, polling=false, disposed=false
function explain(e:unknown){const detail=(e as {response?:{data?:{detail?:unknown}}})?.response?.data?.detail;return typeof detail==='string'?detail:'Não foi possível concluir a consulta. Tente novamente.'}
function usd(v:number|null|undefined){return v===null||v===undefined?'—':v.toLocaleString('pt-BR',{style:'currency',currency:'USD',minimumFractionDigits:2})}
function amount(v:number|null,c:string){return v===null?'—':v.toLocaleString('pt-BR',{style:'currency',currency:c,maximumFractionDigits:c==='PYG'?0:2})}
function date(v:string|null|undefined){return v?new Date(v).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'—'}
const periodLabel=computed(()=>`${month.value ? monthNames[month.value-1] : 'Todos os meses'} · ${year.value || 'todo o histórico'}`)
const annualRows=computed(()=>data.value?.annual.filter(a=>!year.value||a.year===year.value)||[])
const annualTotal=computed(()=>{const vals=annualRows.value.filter(a=>a.total_usd!==null);return vals.length?vals.reduce((n,a)=>n+(a.total_usd||0),0):null})
const annualCoverage=computed(()=>annualRows.value.reduce((n,a)=>n+a.available_months,0))
const sellerPosition=computed(()=>{const i=data.value?.ranking.findIndex(r=>r.name===seller.value)??-1;return i<0?'—':`${i+1}º lugar`})
const visibleMonths=computed(()=>[...(data.value?.months||[])].filter(m=>(!year.value||m.year===year.value)&&(!month.value||m.month===month.value)).reverse())
const visibleSources=computed(()=>status.value?.sources.filter(s=>!onlyIssues.value||s.error||s.warnings.length)||[])
function rankWidth(v:number){return Math.max(0,Math.min(100,v/Math.max(1,data.value?.ranking[0]?.total_usd||1)*100))}
const trendYears=computed(()=>year.value?[year.value]:[...(data.value?.years||[])].reverse())
const trendChart=computed(()=>({labels:monthNames.map(m=>m.slice(0,3)),datasets:trendYears.value.map((y,i)=>({label:String(y),data:monthNames.map((_,n)=>data.value?.months.find(m=>m.year===y&&m.month===n+1)?.total_usd??null),borderColor:palette[i%palette.length],backgroundColor:palette[i%palette.length]+'15',pointRadius:3,pointHoverRadius:6,tension:.25,fill:trendYears.value.length===1,spanGaps:false,borderWidth:2.5}))}))
const comparisonRows=computed(()=>{const rows=(data.value?.comparison||[]).filter(m=>compareYears.value.includes(m.year));return rows.map((m,i)=>{const previous=rows[i-1],delta=m.total_usd!==null&&previous&&previous.total_usd!==null?m.total_usd-previous.total_usd:null;return {...m,delta,previous:previous?.year,percent:delta!==null&&previous?.total_usd?delta/previous.total_usd*100:null}})})
const comparisonChart=computed(()=>({labels:comparisonRows.value.map(m=>String(m.year)),datasets:[{label:seller.value||'Vendas',data:comparisonRows.value.map(m=>m.total_usd),backgroundColor:comparisonRows.value.map((m,i)=>m.partial?'#93c5fd':palette[i%palette.length]),borderRadius:7,maxBarThickness:95}]}))
const lineOptions:ChartOptions<'line'>={responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{display:true,position:'bottom',labels:{usePointStyle:true,boxWidth:7,padding:18}},tooltip:{callbacks:{label:c=>`${c.dataset.label}: ${usd(c.parsed.y)}`}}},scales:{x:{grid:{display:false}},y:{beginAtZero:true,grid:{color:'#eef2f7'},ticks:{callback:v=>Number(v).toLocaleString('pt-BR',{notation:'compact'})}}}}
const barOptions:ChartOptions<'bar'>={responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>usd(c.parsed.y)}}},scales:{x:{grid:{display:false}},y:{beginAtZero:true,grid:{color:'#eef2f7'},ticks:{callback:v=>Number(v).toLocaleString('pt-BR',{notation:'compact'})}}}}
async function load(){const request=++sequence;loading.value=true;error.value='';try{const result=await salesBi.overview({year:year.value||undefined,month:month.value||undefined,seller:seller.value||undefined});if(request===sequence)data.value=result}catch(e){if(request===sequence)error.value=explain(e)}finally{if(request===sequence)loading.value=false}}
async function refresh(){refreshing.value=true;try{await salesBi.sync();notice.value='Leitura solicitada. O painel será atualizado automaticamente ao terminar.';status.value=await salesBi.status()}catch(e){error.value=explain(e)}finally{refreshing.value=false}}
async function openConfig(){try{config.value=(await salesBi.config())||config.value;configOpen.value=true}catch(e){error.value=explain(e)}}
async function saveConfig(){saving.value=true;try{await salesBi.save({...config.value,current_year:config.value.current_year||null,current_month:config.value.current_month||null});configOpen.value=false;notice.value='Fontes salvas. A leitura começará automaticamente.';status.value=await salesBi.status()}catch(e){error.value=explain(e)}finally{saving.value=false}}
function exportCsv(){const cell=(v:unknown)=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const rows=[['Ano','Mês','Vendedor','Total USD','Situação','Fonte'],...visibleMonths.value.map(m=>[m.year,monthNames[m.month-1],seller.value||'Toda a equipe',m.total_usd?.toFixed(2).replace('.',','),m.partial?'Em andamento':'Mensal',m.filename])];const url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='eleven-resumo-vendas.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
onMounted(async()=>{try{const [initial,state]=await Promise.all([salesBi.overview({}),salesBi.status()]);data.value=initial;status.value=state;year.value=initial.latest.year||0;month.value=initial.latest.month||0;compareYears.value=initial.years.slice(0,3);await load()}catch(e){error.value=explain(e)}if(disposed)return;timer=setInterval(async()=>{if(polling)return;polling=true;try{const state=await salesBi.status();const changed=state.finished_at!==status.value?.finished_at;status.value=state;if(changed){if(!data.value?.years.length){const initial=await salesBi.overview({});year.value=initial.latest.year||0;month.value=initial.latest.month||0;compareYears.value=initial.years.slice(0,3)}await load()}}catch{ /* Retain the visible data during a temporary outage. */ }finally{polling=false}},10000)})
onUnmounted(()=>{disposed=true;clearInterval(timer);sequence++})
